/* Signature Hungarian Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Istvanor": "From Istvan + or (gold?).", "Katalinvirag": "From Katalin + virag (flower): 'pure flower'.", "Janoshegy": "From Janos + hegy (hill).", "Erzsebetarany": "From Erzsebet + arany (gold).", "Laszlovitez": "From Laszlo + vitez (knight).", "Mariahold": "From Maria + hold (moon).", "Viragos": "From virag (flower) + -os: Signature surname, 'flowery'.", "Aranyos": "From arany (gold) + -os: Signature surname, 'golden'.", "Hegyesi": "From hegy (hill) + -si: Signature surname, 'of the hill'.", "Holdasi": "From hold (moon) + -si: Signature surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Istvanor';
console.log(lookup(q));

